begin;
insert into public.ce_course3_resources(id,data) values
('course3_module1_pdf','{"base64": "", "sha256": "f2fdffb8bb05047ad0764fd2e365e64cb3aa46f35a1f12fa664f6a2a67afd669", "filename": "CE_HALO_Course3_Module01_Scope_of_Practice_Learner_FINAL.pdf", "mime_type": "application/pdf"}'::jsonb),
('course3_module1_questions','[{"module_id": "course_3_module_1", "question_id": "course_3_module_1_q01", "question_number": 1, "stem": "Which of the following most accurately describes how a CRNA''s legal scope of practice is determined at any given moment?", "choice_a": "By the combined effect of federal law, state law, board of nursing rules, facility bylaws, payer requirements, credentialing, and professional standards — with the more restrictive applicable rule controlling", "choice_b": "By state law alone", "choice_c": "By federal Medicare Conditions of Participation alone", "choice_d": "By AANA policy alone", "correct_choice": "a", "rationale": "CRNA scope is determined by layered sources. When state and federal requirements overlap, the more restrictive applicable rule controls. Facility bylaws and payer contracts may be more restrictive than either.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_1", "question_id": "course_3_module_1_q02", "question_number": 2, "stem": "Per the 2026 AANA Scope of Nurse Anesthesia Practice, CRNAs/nurse anesthesiologists are formally described as:", "choice_a": "Certified nursing assistants with advanced training", "choice_b": "Advanced practice registered nurses (APRNs) licensed as independent practitioners who plan and deliver anesthesia, pain management, and related care", "choice_c": "Registered nurses functioning under physician delegation", "choice_d": "Physician assistants specializing in anesthesia", "correct_choice": "b", "rationale": "The 2026 AANA scope defines CRNAs/nurse anesthesiologists as APRNs licensed as independent practitioners who plan and deliver anesthesia, pain management, and related care across the lifespan.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_1", "question_id": "course_3_module_1_q03", "question_number": 3, "stem": "As of July 2026, approximately how many states plus U.S. territories have opted out of the CMS physician-supervision requirement for CRNAs?", "choice_a": "All 50 states plus Guam and Puerto Rico", "choice_b": "22 states plus Guam", "choice_c": "27 states plus Guam", "choice_d": "17 states, no territories", "correct_choice": "c", "rationale": "Per the AANA July 2026 Fact Sheet Concerning State Opt-Outs, 27 states plus Guam have opted out. Vermont and Ohio were the most recent (both July 2026).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_1", "question_id": "course_3_module_1_q04", "question_number": 4, "stem": "A CRNA practices in a state that has opted out of the federal CMS physician-supervision requirement, but the hospital''s medical staff bylaws still require anesthesiologist supervision for all cases. What must the CRNA do?", "choice_a": "Report the facility to CMS for noncompliance", "choice_b": "Refuse to work until the bylaws are amended", "choice_c": "Ignore the bylaws because the state opt-out overrides them", "choice_d": "Follow the facility bylaws because they are more restrictive; opt-out only removes the federal supervision condition and does not override facility rules", "correct_choice": "d", "rationale": "Per AANA, an opt-out does not permit a CRNA to practice outside state law or override facility rules. Individual facilities may still require CRNAs to be physician-supervised regardless of opt-out status.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_1", "question_id": "course_3_module_1_q05", "question_number": 5, "stem": "Which federal regulation establishes the physician-supervision requirement for anesthesia services in Medicare-participating hospitals?", "choice_a": "42 CFR §482.52", "choice_b": "42 USC §1395dd (EMTALA)", "choice_c": "45 CFR §164.502", "choice_d": "21 CFR §1301.11", "correct_choice": "a", "rationale": "42 CFR §482.52 is the Anesthesia Services Condition of Participation for hospitals. §485.639 covers critical access hospitals; §416.42 covers ambulatory surgical centers.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_1", "question_id": "course_3_module_1_q06", "question_number": 6, "stem": "Per NCSBN, which of the following best describes the Independent category for CRNA practice authority?", "choice_a": "The CRNA is exempt from facility credentialing", "choice_b": "No requirement for a written collaborative agreement, no supervision, no conditions for practice (may follow a statutorily required transition period)", "choice_c": "State law requires no license or registration for CRNA practice", "choice_d": "The CRNA may practice without any state license as long as national certification is current", "correct_choice": "b", "rationale": "Per the NCSBN CRNA Independent Practice Map, Independent means no requirement for a written collaborative agreement, no supervision, and no conditions for practice, though a statutorily required transition period may still precede independent authority.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_1", "question_id": "course_3_module_1_q07", "question_number": 7, "stem": "How does prescriptive authority differ from anesthesia practice authority for a CRNA?", "choice_a": "Prescriptive authority applies only to over-the-counter medications", "choice_b": "Anesthesia practice authority automatically confers full state and federal prescriptive authority", "choice_c": "Prescriptive authority describes prescribing pharmacologic and non-pharmacologic therapies beyond the perioperative and periprocedural periods and is legally distinct from perioperative medication administration", "choice_d": "They are the same thing under federal law", "correct_choice": "c", "rationale": "Per NCSBN and federal regulations, prescriptive authority extends beyond the perioperative period. CRNAs may order and administer controlled substances perioperatively within anesthesia scope without independent prescriptive authority, but broader prescribing requires state prescriptive authority.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_1", "question_id": "course_3_module_1_q08", "question_number": 8, "stem": "Under what federal regulation does a CRNA obtain individual DEA registration as a mid-level practitioner?", "choice_a": "42 CFR §416.42", "choice_b": "42 CFR §482.52", "choice_c": "45 CFR §160.103", "choice_d": "21 CFR §1301.11 (with mid-level classification under §1301.13)", "correct_choice": "d", "rationale": "21 CFR §1301.11 establishes the general DEA registration requirement; §1301.13 addresses mid-level practitioner classification, which is the applicable pathway for CRNA DEA registration.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_1", "question_id": "course_3_module_1_q09", "question_number": 9, "stem": "A CRNA is asked to add ketamine infusion services in an office-based setting. Which of the following is the most complete pre-service verification?", "choice_a": "Confirm state law authorization, professional standard support, facility privileging, individual documented competence, and controlled-substance / DEA compliance", "choice_b": "Check state prescriptive authority only", "choice_c": "Rely on the CMS opt-out because ketamine is administered by a practitioner", "choice_d": "Check facility privileges only", "correct_choice": "a", "rationale": "The five-step framework requires verification across state authorization, professional standard, competence, facility privileging, and downstream documentation/CSR requirements. CMS opt-out is irrelevant to office-based ketamine services.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_1", "question_id": "course_3_module_1_q10", "question_number": 10, "stem": "Which statement about the Nurse Licensure Compact (NLC) is correct for a CRNA planning multistate travel practice?", "choice_a": "The NLC has been repealed and no compact exists", "choice_b": "The NLC covers RN and LPN licensure only; APRN licensure is not covered by the NLC — a separate APRN Compact is being implemented state by state", "choice_c": "The NLC allows practice in any state as long as national certification is current", "choice_d": "The NLC covers RN, LPN, and all APRN licensure across member states", "correct_choice": "b", "rationale": "The NLC does not cover APRN licensure. The APRN Compact adopted by NCSBN in 2020 is being implemented state by state; CRNAs must verify current APRN licensure status in every state where they practice.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_1", "question_id": "course_3_module_1_q11", "question_number": 11, "stem": "A state opt-out under CMS §482.52(c) is effective:", "choice_a": "Upon publication in the Federal Register", "choice_b": "Only after unanimous state legislature approval", "choice_c": "Upon submission by the governor''s letter of attestation to CMS", "choice_d": "60 days after CMS approval", "correct_choice": "c", "rationale": "The 2001 CMS rule permits a state governor to opt out via letter of attestation; the opt-out is effective upon submission. Withdrawal is likewise effective upon submission.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_1", "question_id": "course_3_module_1_q12", "question_number": 12, "stem": "Which of the following is required in a governor''s opt-out letter of attestation to CMS?", "choice_a": "A federal impact statement filed with HHS", "choice_b": "Written concurrence from the state anesthesiology society", "choice_c": "Certification that the state legislature has voted in favor", "choice_d": "Consultation with state boards of medicine and nursing about access and quality; statement that opt-out is in the best interests of state citizens; consistency with state law", "correct_choice": "d", "rationale": "Per the 2001 CMS rule, the governor''s attestation must affirm consultation with state boards of medicine and nursing, that opt-out is in the best interests of citizens, and that it is consistent with state law.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_1", "question_id": "course_3_module_1_q13", "question_number": 13, "stem": "When state law authorizes independent CRNA practice but a Medicare-participating facility''s medical staff bylaws require physician supervision, the CRNA''s anesthesia record should:", "choice_a": "Accurately reflect whether required supervisory contact actually occurred; documentation must never imply supervision that did not happen", "choice_b": "Copy prior anesthetic records for consistency", "choice_c": "Omit any reference to supervision to avoid billing complications", "choice_d": "Document supervision in the record regardless of whether it occurred", "correct_choice": "a", "rationale": "Documentation is a legal record. It must accurately reflect the applicable practice model; misrepresentation may create billing, regulatory, malpractice, or disciplinary risk.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_1", "question_id": "course_3_module_1_q14", "question_number": 14, "stem": "Which resource is most authoritative for verifying the current opt-out status of a specific state?", "choice_a": "A commercial locum tenens agency", "choice_b": "The AANA Fact Sheet Concerning State Opt-Outs (updated periodically) and the CMS Anesthesiologists Information Center", "choice_c": "The state department of transportation", "choice_d": "A general internet search result", "correct_choice": "b", "rationale": "Primary sources are authoritative: the AANA Fact Sheet is maintained specifically for opt-out tracking, and the CMS Anesthesiologists Information Center publishes federal guidance.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_1", "question_id": "course_3_module_1_q15", "question_number": 15, "stem": "A CRNA moves from an opt-out state with full independent practice authority to a state that requires a written collaborative agreement with a physician. What is the correct next step before beginning practice?", "choice_a": "Rely on the prior state''s independent authority until license renewal", "choice_b": "Assume federal CMS opt-out from the prior state carries over", "choice_c": "Verify state APRN license, obtain the required written collaborative agreement, update DEA registration address, verify state CSR, review facility bylaws, and confirm malpractice coverage in the new state", "choice_d": "Practice only under general supervision without a written agreement", "correct_choice": "c", "rationale": "Multistate practice requires per-state verification: licensure, agreements, DEA/CSR, facility credentialing, and malpractice must all be current in the new state.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_1", "question_id": "course_3_module_1_q16", "question_number": 16, "stem": "Which of the following is NOT a legally required verification when a CRNA begins prescribing controlled substances outside the perioperative period in a new state?", "choice_a": "State controlled-substance registration (if required by the state)", "choice_b": "Current DEA registration under 21 CFR §1301.11", "choice_c": "State APRN prescriptive authority", "choice_d": "Local hospital''s marketing department approval", "correct_choice": "d", "rationale": "Hospital marketing approval is not a legal requirement. DEA registration, state CSR, and state APRN prescriptive authority are all required prior to non-perioperative controlled-substance prescribing.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_1", "question_id": "course_3_module_1_q17", "question_number": 17, "stem": "Which statement about “medical direction” is most accurate?", "choice_a": "It is primarily a Medicare billing and anesthesia care-team concept rather than a state licensure requirement, and terminology varies across states", "choice_b": "It has been eliminated from federal regulation", "choice_c": "It is identical to “independent practice”", "choice_d": "It is a state licensure requirement in all 50 states", "correct_choice": "a", "rationale": "Medical direction is largely a Medicare billing concept (TEFRA / 7 steps) and anesthesia care-team term. State licensure terminology (supervision, collaboration, consultation) is distinct and jurisdiction-specific.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_1", "question_id": "course_3_module_1_q18", "question_number": 18, "stem": "A CRNA in a physician-supervision state accepts a locum tenens assignment in a CMS opt-out state at a critical access hospital. What determines whether the CRNA must be supervised at that facility?", "choice_a": "Only federal CMS rules, because CAHs are federally regulated", "choice_b": "The combination of the destination state''s practice authority law and the CAH''s own bylaws and medical staff rules — federal supervision has been removed by the opt-out, so state and facility rules govern", "choice_c": "The rules of the state where the CRNA obtained anesthesia education", "choice_d": "The rules of the CRNA''s home state", "correct_choice": "b", "rationale": "The opt-out removes the federal supervision Condition of Participation, so the destination state''s practice authority law and the facility''s bylaws control whether supervision is required at that CAH.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_1", "question_id": "course_3_module_1_q19", "question_number": 19, "stem": "Per the 2026 AANA scope, the scope of an individual CRNA''s practice is determined by:", "choice_a": "The CRNA''s malpractice insurer", "choice_b": "The physician''s preference", "choice_c": "Education, experience, local law, state law, federal law, and organization policy", "choice_d": "AANA policy alone", "correct_choice": "c", "rationale": "The 2026 AANA scope explicitly states that the individual CRNA''s scope is determined by education, experience, local law, state law, federal law, and organization policy.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_1", "question_id": "course_3_module_1_q20", "question_number": 20, "stem": "What is the practical difference between legal scope and individual competence for a CRNA?", "choice_a": "They are identical", "choice_b": "Competence overrides legal scope in all cases", "choice_c": "Facility privileging overrides both", "choice_d": "Legal scope defines what a CRNA may do; individual competence defines what a CRNA should do safely and ethically; facility privileging defines what a CRNA is authorized to do at a specific site — all three must align", "correct_choice": "d", "rationale": "Safe practice requires alignment among legal authority, individual competence, and institutional authorization. A procedure may be legal but require additional competence or facility privileges before performance.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_1", "question_id": "course_3_module_1_q21", "question_number": 21, "stem": "Which of the following is the correct sequence for CRNA legal research when preparing to add a new office-based anesthesia service?", "choice_a": "State board of nursing → related state statutes (pharmacy, CSR, office-based rules) → federal (CMS, DEA) → professional standards → facility policy", "choice_b": "Facility policy → payer contract only", "choice_c": "DEA only, because controlled substances are involved", "choice_d": "Search social media first, then confirm with the facility", "correct_choice": "a", "rationale": "The recommended research order is board of nursing → other state statutes → federal → professional standards → facility, then reconcile with the more restrictive rule governing.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_1", "question_id": "course_3_module_1_q22", "question_number": 22, "stem": "If a CRNA in a supervised practice state is asked by a surgeon to perform a procedure that exceeds the CRNA''s granted facility privileges, the CRNA should:", "choice_a": "Perform the procedure to maintain the OR schedule", "choice_b": "Pause the activity, seek clarification, escalate through the chain of command, and document the consultation before proceeding — even under supervision, the CRNA remains accountable for practicing within licensure, competence, standards, and facility policy", "choice_c": "Refuse and report the surgeon to the state medical board", "choice_d": "Ask the surgeon to co-sign the record and proceed", "correct_choice": "b", "rationale": "Even under supervision or medical direction, the CRNA retains personal accountability. Requests exceeding scope, privileges, or competence should be paused, escalated, and documented before proceeding.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_1", "question_id": "course_3_module_1_q23", "question_number": 23, "stem": "A payer contract requires physician co-signature on every CRNA anesthesia record, even in an opt-out state with full state independent practice authority. Which of the following is the most accurate compliance conclusion?", "choice_a": "State opt-out overrides all payer contracts", "choice_b": "The CRNA may ignore the payer requirement because state law is independent", "choice_c": "Payer contracts may be more restrictive than state or federal law and must be followed as long as the contract is in force; the CRNA should confirm the requirement with billing and risk management", "choice_d": "Payer contracts have no legal effect on CRNA practice", "correct_choice": "c", "rationale": "Payer contracts can create requirements more restrictive than state or federal law. The CRNA must comply while the contract is in force and coordinate with billing and risk management if the requirement is unclear.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_1", "question_id": "course_3_module_1_q24", "question_number": 24, "stem": "Which of the following is a legitimate use of the AANA Practice in Your State resource?", "choice_a": "As a replacement for state board of nursing advisory opinions", "choice_b": "As an authoritative source for facility bylaws", "choice_c": "As a substitute for reading the state nurse practice act", "choice_d": "As a starting point that identifies opt-out status, prescriptive authority map, and quicklinks, to be verified against the actual state nurse practice act, board rules, and current statute", "correct_choice": "d", "rationale": "Professional resources like AANA Practice in Your State are excellent starting points but should not replace review of the current state nurse practice act, board rules, and advisory opinions.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_1", "question_id": "course_3_module_1_q25", "question_number": 25, "stem": "When a state has full independent CRNA practice authority but the facility bylaws and payer both require anesthesiologist supervision, the applicable operational rule is:", "choice_a": "The most restrictive applicable rule — in this case, the facility bylaws and payer requirement — must be followed while in that facility and under that payer", "choice_b": "Only the CRNA''s individual judgment", "choice_c": "State law, because it is the most permissive source", "choice_d": "Federal Medicare rules, regardless of opt-out", "correct_choice": "a", "rationale": "The bedrock rule of layered CRNA scope is that the more restrictive applicable requirement always controls. State independent authority does not override facility bylaws or payer contracts.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}]'::jsonb)
on conflict(id) do update set data=excluded.data;
do $$ begin
assert (select encode(sha256(decode(data->>'base64','base64')),'hex')=data->>'sha256' from public.ce_course3_resources where id='course3_module1_pdf'),'PDF hash mismatch';
assert (select released=false from public.ce_course3_catalog where id='1047243'),'Course must remain staged';
end $$;
commit;